/** Original interpretive copy for the Rider–Waite–Smith deck.
 * Themes form a shared vocabulary across suits and orientations so the local
 * reading engine can identify meaningful relationships rather than name matches.
 */
export type Suit = 'wands' | 'cups' | 'swords' | 'pentacles';
export type Meaning = { keywords: string[]; text: string; advice: string; themes: string[] };
export type TarotCard = {
  id: string; name: string; arcana: 'major' | 'minor'; number: number;
  suit?: Suit; rank?: string; image: string; upright: Meaning; reversed: Meaning;
};
type Entry = readonly [name: string, uprightKeywords: string, uprightText: string, uprightAdvice: string, uprightThemes: string, reversedKeywords: string, reversedText: string, reversedAdvice: string, reversedThemes: string];

