const ranks = ['Ace', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Page', 'Knight', 'Queen', 'King'];
function card(entry: Entry, number: number, suit?: Suit): TarotCard {
  const [name, uk, ut, ua, uth, rk, rt, ra, rth] = entry;
  const id = `${suit ?? 'major'}-${String(number).padStart(2, '0')}`;
  return {
    id, name, arcana: suit ? 'minor' : 'major', number,
    ...(suit ? { suit, rank: ranks[number - 1] } : {}),
    image: `/cards/${id}.webp`,
    upright: { keywords: uk.split('|'), text: ut, advice: ua, themes: uth.split('|') },
    reversed: { keywords: rk.split('|'), text: rt, advice: ra, themes: rth.split('|') },
  };
}
export const cards: TarotCard[] = [
  ...major.map((entry, i) => card(entry, i)),
  ...wands.map((entry, i) => card(entry, i + 1, 'wands')),
  ...cups.map((entry, i) => card(entry, i + 1, 'cups')),
  ...swords.map((entry, i) => card(entry, i + 1, 'swords')),
  ...pentacles.map((entry, i) => card(entry, i + 1, 'pentacles')),
];
